static FILE* logfout=nullptr;
static void L(const char* f,...){ va_list a; va_start(a,f); vprintf(f,a); va_end(a); if(logfout){va_start(a,f);vfprintf(logfout,f,a);va_end(a);fflush(logfout);} }
static DWORD pidof(const wchar_t* n){ PROCESSENTRY32W e{sizeof(e)}; HANDLE h=CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS,0); if(h==INVALID_HANDLE_VALUE)return 0; DWORD p=0; if(Process32FirstW(h,&e))do{if(!_wcsicmp(e.szExeFile,n)){p=e.th32ProcessID;break;}}while(Process32NextW(h,&e));CloseHandle(h);return p; }
static bool rdprot(DWORD p){ if(p&PAGE_GUARD)return false;p&=0xff;return p==PAGE_READONLY||p==PAGE_READWRITE||p==PAGE_WRITECOPY||p==PAGE_EXECUTE_READ||p==PAGE_EXECUTE_READWRITE||p==PAGE_EXECUTE_WRITECOPY; }
static std::string hx(const uint8_t*p,size_t n){std::ostringstream o;o<<std::hex<<std::setfill('0');for(size_t i=0;i<n;i++)o<<std::setw(2)<<(unsigned)p[i];return o.str();}
static bool load(const wchar_t*p,std::vector<uint8_t>&b){std::ifstream f(p,std::ios::binary);if(!f)return false;b.assign(std::istreambuf_iterator<char>(f),{});return true;}
static bool aes(const uint8_t k32[32],const uint8_t ct[16],uint8_t pt[16]){BCRYPT_ALG_HANDLE a=0;BCRYPT_KEY_HANDLE k=0;DWORD cb=0,ol=0,on=0;if(BCryptOpenAlgorithmProvider(&a,BCRYPT_AES_ALGORITHM,0,0)<0)return false;BCryptSetProperty(a,BCRYPT_CHAINING_MODE,(PUCHAR)BCRYPT_CHAIN_MODE_ECB,sizeof(BCRYPT_CHAIN_MODE_ECB),0);if(BCryptGetProperty(a,BCRYPT_OBJECT_LENGTH,(PUCHAR)&ol,sizeof(ol),&cb,0)<0){BCryptCloseAlgorithmProvider(a,0);return false;}std::vector<uint8_t>o(ol);if(BCryptGenerateSymmetricKey(a,&k,o.data(),ol,(PUCHAR)k32,32,0)<0){BCryptCloseAlgorithmProvider(a,0);return false;}auto s=BCryptDecrypt(k,(PUCHAR)ct,16,0,0,0,pt,16,&on,0);BCryptDestroyKey(k);BCryptCloseAlgorithmProvider(a,0);return s>=0&&on==16;}
static bool sha256(const uint8_t*p,size_t n,uint8_t out[32]){BCRYPT_ALG_HANDLE a=0;BCRYPT_HASH_HANDLE h=0;DWORD cb=0,ol=0,hl=0;if(BCryptOpenAlgorithmProvider(&a,BCRYPT_SHA256_ALGORITHM,0,0)<0)return false;if(BCryptGetProperty(a,BCRYPT_OBJECT_LENGTH,(PUCHAR)&ol,sizeof(ol),&cb,0)<0){BCryptCloseAlgorithmProvider(a,0);return false;}if(BCryptGetProperty(a,BCRYPT_HASH_LENGTH,(PUCHAR)&hl,sizeof(hl),&cb,0)<0||hl!=32){BCryptCloseAlgorithmProvider(a,0);return false;}std::vector<uint8_t>o(ol);if(BCryptCreateHash(a,&h,o.data(),ol,0,0,0)<0){BCryptCloseAlgorithmProvider(a,0);return false;}BCryptHashData(h,(PUCHAR)p,(ULONG)n,0);auto s=BCryptFinishHash(h,out,32,0);BCryptDestroyHash(h);BCryptCloseAlgorithmProvider(a,0);return s>=0;}
static bool ishex(const std::string&s){for(char c:s)if(!((c>='0'&&c<='9')||(c>='a'&&c<='f')||(c>='A'&&c<='F')))return false;return true;}
static bool dehex(const std::string&s,uint8_t o[32]){if(s.size()!=64||!ishex(s))return false;auto v=[](char c){return c<='9'?c-'0':(c<='F'?c-'A'+10:c-'a'+10);};for(int i=0;i<32;i++)o[i]=(uint8_t)((v(s[i*2])<<4)|v(s[i*2+1]));return true;}
static bool deb64(const std::string&s,uint8_t o[32]){DWORD n=32;if(!CryptStringToBinaryA(s.c_str(),(DWORD)s.size(),CRYPT_STRING_BASE64,o,&n,0,0))return false;return n==32;}
static bool validkey(const uint8_t k[32],const uint8_t ct[16],const char*how,uintptr_t fs,const std::string&str){uint8_t p[16]{};if(!aes(k,ct,p))return false;if(!memcmp(p,"GVAS",4)){L("*** VALID_SAVE_KEY *** method=%s FStringVA=0x%llx inferred_UAPKSaveGameManager=0x%llx\n",how,(unsigned long long)fs,(unsigned long long)(fs-0x30));L("key_hex=%s\n",hx(k,32).c_str());L("EncryptKey_text=%s\n",str.c_str());L("first_decrypted=%s\n",hx(p,16).c_str());return true;}return false;}
static std::string utf8(const std::vector<wchar_t>&w,size_t chars){if(!chars)return{};int n=WideCharToMultiByte(CP_UTF8,0,w.data(),(int)chars,0,0,0,0);if(n<=0)return{};std::string s(n,'\0');WideCharToMultiByte(CP_UTF8,0,w.data(),(int)chars,s.data(),n,0,0);return s;}
int wmain(int ac,wchar_t**av){const wchar_t*save=ac>1?av[1]:L"DefaultData.sav";logfout=_wfopen(L"APK2_FStringKeyProbe.txt",L"wb");L("APK2 FString EncryptKey Probe v1 - READ ONLY\nknown reflection: UAPKSaveGameManager::EncryptKey is FString at +0x30\n");std::vector<uint8_t>sv;if(!load(save,sv)||sv.size()<16){L("ERROR save not readable; pass native PC DefaultData.sav path\n");return 2;}uint8_t ct[16];memcpy(ct,sv.data(),16);L("save_size=%llu ct0=%s\n",(unsigned long long)sv.size(),hx(ct,16).c_str());DWORD pid=pidof(L"APK2-Win64-Shipping.exe");if(!pid){L("ERROR game process not found\n");return 3;}HANDLE hp=OpenProcess(PROCESS_QUERY_INFORMATION|PROCESS_VM_READ,FALSE,pid);if(!hp){L("ERROR OpenProcess %lu; run as Administrator\n",GetLastError());return 4;}L("pid=%lu\n",pid);SYSTEM_INFO si{};GetSystemInfo(&si);uintptr_t a=(uintptr_t)si.lpMinimumApplicationAddress,mx=(uintptr_t)si.lpMaximumApplicationAddress;MEMORY_BASIC_INFORMATION m{};size_t regs=0,structs=0,strings=0,tests=0,hits=0;std::unordered_set<std::string>seen;while(a<mx&&VirtualQueryEx(hp,(void*)a,&m,sizeof(m))==sizeof(m)){uintptr_t nx=a+m.RegionSize;if(nx<=a)break;if(m.State==MEM_COMMIT&&rdprot(m.Protect)&&m.RegionSize&&m.RegionSize<=(256ull<<20)){std::vector<uint8_t>b((size_t)m.RegionSize);SIZE_T got=0;if(ReadProcessMemory(hp,m.BaseAddress,b.data(),b.size(),&got)&&got){b.resize(got);regs++;for(size_t i=0;i+16<=b.size();i+=8){uintptr_t ptr=0;int32_t num=0,cap=0;memcpy(&ptr,b.data()+i,8);memcpy(&num,b.data()+i+8,4);memcpy(&cap,b.data()+i+12,4);if(ptr<0x10000||num<2||num>129||cap<num||cap>256||(ptr&1))continue;structs++;std::vector<wchar_t>w(num);SIZE_T g=0;if(!ReadProcessMemory(hp,(void*)ptr,w.data(),num*sizeof(wchar_t),&g)||g!=num*sizeof(wchar_t))continue;if(w.back()!=0)continue;size_t chars=num-1;if(chars<4||chars>128)continue;bool printable=true;for(size_t j=0;j<chars;j++){if(w[j]<0x20||w[j]>0x7e){printable=false;break;}}if(!printable)continue;std::string s=utf8(w,chars);if(s.empty()||!seen.insert(s).second)continue;strings++;uintptr_t fs=(uintptr_t)m.BaseAddress+i;uint8_t k[32]{};bool any=false;if(s.size()==32){memcpy(k,s.data(),32);tests++;any|=validkey(k,ct,"raw-32-ascii",fs,s);}if(s.size()==64&&dehex(s,k)){tests++;any|=validkey(k,ct,"hex-64",fs,s);}if((s.size()==43||s.size()==44)&&deb64(s,k)){tests++;any|=validkey(k,ct,"base64-32",fs,s);}if(s.size()<=32){memset(k,0,32);memcpy(k,s.data(),s.size());tests++;any|=validkey(k,ct,"ascii-zero-pad",fs,s);}if(s.size()>=32){memcpy(k,s.data(),32);tests++;any|=validkey(k,ct,"ascii-first32",fs,s);}if(sha256((const uint8_t*)s.data(),s.size(),k)){tests++;any|=validkey(k,ct,"sha256-utf8",fs,s);}if(sha256((const uint8_t*)w.data(),chars*sizeof(wchar_t),k)){tests++;any|=validkey(k,ct,"sha256-utf16le",fs,s);}if(any)hits++;}}}a=nx;}L("SUMMARY regions=%llu FString_struct_candidates=%llu unique_printable_FStrings=%llu key_tests=%llu valid_hits=%llu\n",(unsigned long long)regs,(unsigned long long)structs,(unsigned long long)strings,(unsigned long long)tests,(unsigned long long)hits);CloseHandle(hp);if(logfout)fclose(logfout);return hits?0:10;}
